 TABLE(["Шкала S&P","Группа","Типичный смысл"],[["AAA, AA","Высший уровень","Очень низкий риск"],["A, BBB","Инвестиционный","Умеренный риск"],["BB, B","Спекулятивный","Заметный риск"],["CCC и ниже","Высокий риск","Дефолт вероятен"]],(2,0)),
